mapper.select:
SELECT b.*, p.project_name, u.real_name as leader_name FROM project_budget b LEFT JOIN research_project p ON b.project_id = p.id LEFT JOIN sys_user u ON p.leader_id = u.id WHERE 1=1
AND p.project_name LIKE CONCAT('%',#{keyword},'%')
AND b.status = #{status}
AND p.leader_id = #{leaderId}
ORDER BY b.create_time DESC
